from collections import OrderedDict
from dataclasses import dataclass
from decimal import Decimal
from typing import Any, Tuple

from vyper import ast as vy_ast
from vyper.abi_types import (
    ABI_Address,
    ABI_Bool,
    ABI_Bytes,
    ABI_BytesM,
    ABI_DynamicArray,
    ABI_FixedMxN,
